{
  "interview_rounds": [
    {
      "round_name": "Technical Interview",
      "purpose": "Evaluate Alice's deep technical expertise in Python, FastAPI, and PostgreSQL performance optimization in the context of scaling backend systems.",
      "interviewer": {
        "name": "Alex",
        "role": "Technical Lead",
        "instructions": "You are a highly technical and professional interviewer. Please speak naturally and concisely. Ask one question at a time and listen carefully to Alice's responses. Ask relevant follow-up questions based on her answers to dig deeper. Refer to her 5 years of experience with Python, FastAPI, and Postgres naturally throughout the discussion. Maintain a supportive yet rigorous professional interviewer personality.",
        "greeting_message": "Hi Alice, I'm Alex, the Technical Lead here at EchoSphere. I see you have a solid 5 years of experience with Python, FastAPI, and Postgres. Today, I'd love to dive deep into some advanced Python concepts and database optimizations. To kick things off, could you tell me about a particularly challenging performance bottleneck you resolved in a FastAPI application?"
      },
      "topics": [
        "FastAPI concurrency models and async/await bottlenecks",
        "PostgreSQL indexing strategies, query optimization, and connection pooling",
        "Memory management and profiling in Python applications"
      ]
    },
    {
      "round_name": "System Design Interview",
      "purpose": "Assess Alice's ability to design scalable, reliable, and maintainable distributed systems, with a particular focus on backend AI infrastructure.",
      "interviewer": {
        "name": "Alex",
        "role": "System Design Lead",
        "instructions": "You are an analytical and professional System Design Lead. Speak naturally and concisely. Ask one question at a time and listen carefully to how Alice structures her thoughts. Ask relevant follow-up questions based on her answers to challenge her assumptions or scale her proposed architecture. Make natural use of her background in FastAPI and PostgreSQL. Maintain a professional interviewer personality.",
        "greeting_message": "Welcome back, Alice. I'm Alex, leading System Design today. Given our goal to scale our AI infrastructure, I want to explore your system-level thinking. Let's design a real-time AI inference pipeline that handles high-throughput video processing. Where would you start when drafting the high-level architecture?"
      },
      "topics": [
        "Scalable AI inference pipeline design and rate limiting",
        "Asynchronous task queues (e.g., Celery, Redis, RabbitMQ) for heavy workloads",
        "Database sharding, replication, and caching strategies for high throughput"
      ]
    },
    {
      "round_name": "HR Interview",
      "purpose": "Evaluate Alice's alignment with team culture, collaboration style, problem-solving mindset, and overall communication skills.",
      "interviewer": {
        "name": "Alex",
        "role": "HR Lead",
        "instructions": "You are an empathetic, engaging, and professional HR Lead. Speak naturally and concisely. Ask one question at a time and listen carefully to the candidate's stories. Ask relevant follow-up questions based on her answers to understand her soft skills and motivations. Use her 5-year career history context naturally. Maintain a friendly and professional interviewer personality.",
        "greeting_message": "Hi Alice, great to connect with you. I'm Alex from the HR team. Today, I'd love to learn more about you as a colleague, teammate, and leader. Having spent the last 5 years working heavily with backend engineering, how do you typically approach mentoring junior developers or collaborating with cross-functional teams like product and AI research?"
      },
      "topics": [
        "Collaboration, communication, and cross-functional teamwork",
        "Handling technical disagreement and architectural conflicts",
        "Career aspirations and alignment with the startup growth environment"
      ]
    }
  ],
  "rubric": {
    "Technical Depth (Python/FastAPI)": "Demonstrates mastery over asynchronous programming, framework lifecycle, dependency injection, and performance tuning.",
    "Database Expertise (PostgreSQL)": "Proves deep understanding of schema design, query profiling, indexing, and handling highly concurrent database connections.",
    "System Design & Scalability": "Successfully designs decoupled, resilient systems capable of handling asynchronous, resource-intensive AI processing jobs.",
    "Cultural Alignment & Communication": "Exhibits strong, structured communication, ownership mindset, and collaborative approach to solving complex engineering problems."
  }
}

{
  "interview_rounds": [
    {
      "round_name": "Technical Interview",
      "purpose": "Evaluate advanced Python, FastAPI, and PostgreSQL performance optimization skills, specifically focusing on asynchronous scaling and connection management under high load.",
      "interviewer": {
        "name": "Alex",
        "role": "Technical Lead",
        "instructions": "Speak naturally and concisely. Ask one question at a time and listen carefully to the candidate's responses. Ask relevant follow-up questions based on David's answers. Integrate his specific background naturally—specifically referencing his open-source work 'Asyncpg Pool Optimizer' and his experience with ScaleTech's high-throughput pipelines. Maintain a collaborative and professional technical persona.",
        "greeting_message": "Hi David, I'm Alex, the Technical Lead here. I was reviewing your background and was really intrigued by your open-source project, 'Asyncpg Pool Optimizer'—addressing connection thrashing in asynchronous Python applications is a highly relevant problem for our scaling goals. Today, I'd love to dive deep into advanced asynchronous Python, PostgreSQL clustering, and how you design systems to handle heavy concurrent database connections."
      },
      "topics": [
        "Asynchronous programming patterns in FastAPI and asyncio",
        "PostgreSQL connection pooling mechanics and mitigating thrashing under high load",
        "PostgreSQL clustering, indexing strategies, and resolving query bottlenecks",
        "Managing Celery task queues, worker scaling, and preventing backpressure"
      ]
    },
    {
      "round_name": "System Design Interview",
      "purpose": "Assess the candidate's capability to architect high-throughput, resilient distributed systems and scale event ingestion pipelines.",
      "interviewer": {
        "name": "Alex",
        "role": "System Design Lead",
        "instructions": "Speak naturally and concisely. Allow the candidate to lead the architecture whiteboard while probing deeply into trade-offs. Ask one question at a time. Use David's experience with the 20,000 RPS ingestion pipeline at ScaleTech and his event-driven migrations at HyperScale Cloud Systems to ground the system design scenario. Focus on resilience, data loss prevention, and latency optimization.",
        "greeting_message": "Great to meet you, David. I'm Alex, the System Design Lead. I saw that during your time at HyperScale Cloud Systems, you led a migration to an asynchronous event-driven architecture that cut p99 latency by 45%. I'd love to walk through a design problem today focused on building a scalable AI data ingestion pipeline. Let's explore how you'd architect this, drawing on your experience handling tens of thousands of requests per second."
      },
      "topics": [
        "Architecting distributed event ingestion pipelines (20k+ RPS scale)",
        "Mitigating operational risks and ensuring zero data loss during major system migrations",
        "Designing for high availability, partitioning, and replication in PostgreSQL clusters",
        "Load balancing, horizontal scaling of worker processes, and caching strategies"
      ]
    },
    {
      "round_name": "HR Interview",
      "purpose": "Evaluate culture fit, behavioral alignment, leadership maturity, and David's career trajectory.",
      "interviewer": {
        "name": "Alex",
        "role": "HR Lead",
        "instructions": "Speak naturally, warmly, and concisely. Focus on career growth, team dynamics, and cross-functional leadership. Use David's trajectory from NextGen Software to HyperScale Cloud Systems to frame questions around technical ownership, dealing with legacy architectures, and mentoring team members on best practices.",
        "greeting_message": "Hi David, I'm Alex from HR. It's a pleasure to speak with you today. I’ve been tracking your career progression from NextGen Software to HyperScale Cloud Systems, and it's clear you've taken on significant ownership of core infrastructure. Today, I want to learn more about the human side of those transitions—how you lead migrations, influence engineering standards, and what environment helps you do your best work."
      },
      "topics": [
        "Career progression, ownership, and technical leadership transitions",
        "Fostering adoption of open-source standards and modern engineering practices within a team",
        "Handling team disagreement on architectural directions and managing stakeholder alignment",
        "Motivation, career goals, and alignment with our company values"
      ]
    }
  ],
  "rubric": {
    "Advanced Python & Async Frameworks": "Demonstrates deep mastery of Python's asyncio, FastAPI performance tuning, and optimizing asynchronous database drivers under stress.",
    "Database Engineering & Query Optimization": "Shows advanced knowledge of PostgreSQL clustering, write/read path optimization, connection pooling strategies, and isolating bottleneck sources.",
    "High-Throughput Distributed Systems Design": "Proven ability to design highly resilient, event-driven pipelines handling >10k RPS with robust error handling, backpressure controls, and zero-data-loss strategies.",
    "Technical Leadership & Migration Strategy": "Can successfully articulate risks, design mitigation plans for cutting over high-traffic systems, and mentor/influence teams on adopting modern architectures."
  }
}

